def decode(encoded: str, original: str, message: str) -> str:
    # Build mapping from encoded to original
    mapping = {}
    for enc_char, orig_char in zip(encoded, original):
        if enc_char in mapping:
            if mapping[enc_char] != orig_char:
                return "Failed"
        else:
            mapping[enc_char] = orig_char

    # Check if all letters in the alphabet are represented
    # We need to ensure that the mapping covers all 26 letters
    # Actually, the problem says "not all letters are represented in the mapping"
    # This likely means that the encoded string doesn't contain all 26 letters
    # Let's check if the set of keys in mapping has size 26
    if len(mapping) != 26:
        return "Failed"

    # Also check that the mapping is a bijection (each original letter maps to exactly one encoded letter)
    # We need to ensure that no two different encoded letters map to the same original letter
    original_values = list(mapping.values())
    if len(set(original_values)) != 26:
        return "Failed"

    # Now decode the message
    decoded = []
    for char in message:
        if char in mapping:
            decoded.append(mapping[char])
        else:
            # If a character in the message is not in the mapping, we can't decode it
            return "Failed"

    return ''.join(decoded)
